SELECT e.EMPLOYEE_ID, e.JOB_ID
FROM employees e
WHERE e.SALARY < (SELECT MIN(salary) FROM employees j WHERE j.JOB_ID = 'MK_MAN');

SELECT technician.Name 
FROM technician
JOIN repair_assignment ON technician.technician_id = repair_assignment.technician_id;

SELECT document_name, document_date 
FROM Documents 
WHERE Project_ID IN (SELECT Project_ID FROM Projects WHERE Project_Details = 'Graph Database project');

SELECT shop.Name 
FROM shop 
WHERE shop.Number_products > (SELECT AVG(Number_products) FROM shop);

SELECT MIN(salary) 
FROM instructor 
WHERE dept_name IN (SELECT dept_name FROM instructor GROUP BY dept_name HAVING AVG(salary) > (SELECT AVG(salary) FROM instructor));

SELECT artwork.Name 
FROM artwork
JOIN nomination ON artwork.Artwork_ID = nomination.Artwork_ID;
